package Tv2.Controller;
import Tv2.View.HocThuPage;
import MainPage.View.Workspace;
import MainPage.Controller.PageTasks;
import Model.*;
import Service.*;
import java.util.*;
import java.time.*;
import java.awt.Component;

/** Xếp buổi thử thật hoặc tạo buổi dự kiến từ thời khóa biểu. */
public class HocThuController {
 private record Key(int lop,LocalDate date,int ca){}
 private record Candidate(int lesson,int rule,int lop,Integer course,String name,LocalDate date,int ca,LocalTime start,LocalTime end,String state){}
 private record Data(List<Candidate> candidates,List<Workspace.Choice> courses){}
 public static void open(Component owner,int b,int hv,Integer course,Runnable done){
  HocThuPage v=new HocThuPage();v.title("XẾP HỌC THỬ — Hồ sơ #"+hv,"Buổi học thực tế và lịch dự kiến trong 6 tuần tới");v.columns("Mã buổi","Lớp","Ngày","Giờ bắt đầu","Giờ kết thúc","Trạng thái");
  Workspace.Choice[] defaultOptions={new Workspace.Choice(0,"Tất cả khóa học")};v.setCourseOptions(defaultOptions,0);List<Candidate> displayed=new ArrayList<>();List<Candidate> all=new ArrayList<>();
  Runnable filter=()->{int key=v.courseId();displayed.clear();all.stream().filter(c->key==0||Objects.equals(c.course,key)).forEach(displayed::add);v.rows(displayed.stream().map(c->new Object[]{c.lesson==0?"Chưa tạo":c.lesson,c.name,c.date,c.start,c.end,c.state}).toArray(Object[][]::new));v.status(displayed.isEmpty()?"Không có buổi phù hợp. Kiểm tra thời khóa biểu.":"Kéo hồ sơ vào dòng buổi học hoặc chọn dòng rồi xác nhận.");};
  v.onCourseChanged(filter);var confirm=v.action("Xác nhận học thử",()->{int r=v.selected();if(r<0||r>=displayed.size()){Workspace.message(v,"Chọn buổi học");return;}Candidate candidate=displayed.get(r);PageTasks.actor(v,b,actor->PageTasks.run(v,()->assign(b,hv,candidate,actor),ok->{done.run();javax.swing.SwingUtilities.getWindowAncestor(v).dispose();}));});confirm.setEnabled(false);Workspace.window(owner,"Xếp học thử",v);
  PageTasks.run(v,()->load(b),d->{all.addAll(d.candidates);v.setCourseOptions(d.courses.toArray(Workspace.Choice[]::new),course==null?0:course);filter.run();confirm.setEnabled(!all.isEmpty());});
 }
 private static Data load(int b){
  var classes=new HashMap<Integer,LopHocModel>();new LopHocService().selectAll(b).stream().filter(l->"DANG_MO".equals(l.getTrangThai())).forEach(l->classes.put(l.getMaLop(),l));var categories=new DanhMucService().selectAll(b);var shifts=new HashMap<Integer,DanhMucModel>();List<Workspace.Choice> courses=new ArrayList<>();courses.add(new Workspace.Choice(0,"Tất cả khóa học"));for(var c:categories){if("CA_HOC".equals(c.getNhomDanhMuc()))shifts.put(c.getMaDanhMuc(),c);if("KHOA_HOC".equals(c.getNhomDanhMuc()))courses.add(new Workspace.Choice(c.getMaDanhMuc(),c.getTenDanhMuc()));}
  Map<Key,BuoiHocModel> actual=new HashMap<>();Map<Key,Candidate> candidates=new HashMap<>();LocalDate now=LocalDate.now();
  for(var l:new BuoiHocService().selectAll(b)){var key=new Key(l.getMaLop(),l.getNgayHoc(),l.getMaCaHoc());actual.put(key,l);var c=classes.get(l.getMaLop());if(c==null||l.getNgayHoc().isBefore(now)||!Set.of("DU_KIEN","DA_KICH_HOAT").contains(l.getTrangThai()))continue;candidates.put(key,new Candidate(l.getMaBuoiHoc(),l.getMaThoiKhoaBieu()==null?0:l.getMaThoiKhoaBieu(),l.getMaLop(),c.getMaKhoaHoc(),c.getTenLop(),l.getNgayHoc(),l.getMaCaHoc(),l.getGioBatDau(),l.getGioKetThuc(),l.getTrangThai()));}
  for(var t:new ThoiKhoaBieuService().selectAll(b)){var c=classes.get(t.getMaLop());var shift=shifts.get(t.getMaCaHoc());if(c==null||shift==null||!t.isTrangThai()||!shift.isTrangThai())continue;LocalTime start,end;try{start=LocalTime.parse(PageTasks.field(shift.getCauHinh(),"GioBatDau"));end=LocalTime.parse(PageTasks.field(shift.getCauHinh(),"GioKetThuc"));if(!end.isAfter(start))continue;}catch(Exception ex){continue;}for(LocalDate date=now;date.isBefore(now.plusWeeks(6));date=date.plusDays(1)){if(date.getDayOfWeek().getValue()!=t.getThuTrongTuan()||date.isBefore(t.getTuNgay())||t.getDenNgay()!=null&&date.isAfter(t.getDenNgay())||date.isBefore(c.getNgayBatDau())||c.getNgayKetThuc()!=null&&date.isAfter(c.getNgayKetThuc()))continue;Key key=new Key(c.getMaLop(),date,t.getMaCaHoc());if(!actual.containsKey(key))candidates.putIfAbsent(key,new Candidate(0,t.getMaThoiKhoaBieu(),c.getMaLop(),c.getMaKhoaHoc(),c.getTenLop(),date,t.getMaCaHoc(),start,end,"Dự kiến từ TKB"));}}
  return new Data(candidates.values().stream().sorted(Comparator.comparing(Candidate::date).thenComparing(Candidate::start).thenComparing(Candidate::name)).toList(),courses);
 }
 private static boolean assign(int b,int hv,Candidate candidate,int actor){
  var hs=new HocVienService();var h=hs.getByMaHocVien(b,hv);PageTasks.require(h!=null&&Set.of("TIEP_NHAN","HOC_THU").contains(h.getTrangThai()),"Hồ sơ không còn ở giai đoạn học thử");PageTasks.require(!candidate.date.isBefore(LocalDate.now()),"Buổi đã qua");var bs=new BuoiHocService();var l=bs.reload(b).stream().filter(x->x.getMaLop()==candidate.lop&&x.getMaCaHoc()==candidate.ca&&candidate.date.equals(x.getNgayHoc())).findFirst().orElse(null);
  if(l==null){var t=new ThoiKhoaBieuService().getByMaThoiKhoaBieu(b,candidate.rule);var c=new LopHocService().getByMaLop(b,candidate.lop);PageTasks.require(t!=null&&t.isTrangThai()&&c!=null&&"DANG_MO".equals(c.getTrangThai())&&!candidate.date.isBefore(t.getTuNgay())&&(t.getDenNgay()==null||!candidate.date.isAfter(t.getDenNgay())),"Lịch đã thay đổi; mở lại cửa sổ");l=new BuoiHocModel();l.setMaLop(candidate.lop);l.setMaThoiKhoaBieu(candidate.rule);l.setNgayHoc(candidate.date);l.setMaCaHoc(candidate.ca);l.setGioBatDau(candidate.start);l.setGioKetThuc(candidate.end);l.setMaGiaoVien(c.getMaGiaoVien());PageTasks.require(bs.insert(b,l),"Không tạo được buổi dự kiến");}
  PageTasks.require(Set.of("DU_KIEN","DA_KICH_HOAT").contains(l.getTrangThai()),"Buổi không còn phù hợp");int lesson=l.getMaBuoiHoc();var ds=new DiemDanhService();var old=ds.getByMaHocVien(b,hv).stream().filter(d->d.getMaBuoiHoc()==lesson).findFirst().orElse(null);if(old==null){DiemDanhModel d=new DiemDanhModel();d.setMaHocVien(hv);d.setMaBuoiHoc(lesson);d.setLoaiThamGia("HOC_THU");d.setMaNguoiCapNhat(actor);PageTasks.require(ds.insert(b,d),"Không tạo được lịch thử");}else PageTasks.require("HOC_THU".equals(old.getLoaiThamGia())&&!"HUY".equals(old.getTrangThai()),"Buổi đã có tham gia hoặc đã hủy");String prev=h.getTrangThai();if(!"HOC_THU".equals(prev)){h.setTrangThai("HOC_THU");PageTasks.require(hs.update(b,h),"Đã ghi lịch thử nhưng chưa chuyển trạng thái hồ sơ");log(b,hv,actor,prev,"HOC_THU",candidate.course);}return true;
 }
 static void log(int b,int hv,int actor,String prev,String next,Integer course){TuongTacHocVienModel t=new TuongTacHocVienModel();t.setMaHocVien(hv);t.setMaNhanSu(actor);t.setLoaiTuongTac("DOI_TRANG_THAI");t.setTrangThaiTruoc(prev);t.setTrangThaiSau(next);t.setMaKhoaHocMongMuon(course);PageTasks.require(new TuongTacHocVienService().insert(b,t),"Đã đổi trạng thái nhưng chưa ghi lịch sử; kiểm tra dữ liệu");}
 public static void convert(Component owner,int b,int hv,Integer course,Runnable done){if(!Workspace.confirm(owner,"Chuyển sang học viên chính thức chưa xếp lớp?"))return;PageTasks.actor(owner,b,actor->PageTasks.run(owner,()->{var hs=new HocVienService();var h=hs.getByMaHocVien(b,hv);PageTasks.require(h!=null&&Set.of("HOC_THU","CHO_XEP_LOP","TIEP_NHAN").contains(h.getTrangThai()),"Không thể chuyển hồ sơ này");String prev=h.getTrangThai();h.setTrangThai("CHINH_THUC");h.setNgayChinhThuc(LocalDate.now());PageTasks.require(hs.update(b,h),"Chưa chuyển được hồ sơ");log(b,hv,actor,prev,"CHINH_THUC",course);return true;},r->done.run()));}
}
